# ============================================================================


def parse_numeric(value):
    """Extract a numeric value from a string like '25 °C' or '100 mM'.

    Call this ONLY for a single-valued field eLabFTW types as a number. On a text field
    it is destructive - '20 mM NaAc' becomes 20.0 and the buffer identity is gone - and
    on a delimited list it keeps only the first element. When in doubt, store the
    original string unchanged.
    """

    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip()
        import re

        match = re.search(r"[-+]?\d*\.?\d+", text.replace(",", "."))
        if match:
            try:
                return float(match.group())
            except ValueError:
                return None
    return None


def parse_field(value, field_type=None):
    """Route an eLabFTW value by what it IS, not by which parameter it came from.

    Any field may arrive as a delimited list, so the delimiter check comes first.
    """
    if value is None or value == "":
        return None
    if isinstance(value, (list, int, float)):
        return value
    text = str(value).strip()
    # a list if a delimiter separates more than one token; "1,5" (decimal comma) is one
    for sep in (";", ","):
        parts = [p.strip() for p in text.split(sep) if p.strip()]
        if len(parts) > 1:
            # Try numeric list; if any element fails, keep as list of strings
            all_numeric = True
            numeric_parts = []
            for p in parts:
                try:
                    numeric_parts.append(float(p.replace(",", ".")))
                except ValueError:
                    all_numeric = False
                    break
            if all_numeric:
                return numeric_parts
            return parts
    if field_type == "number":
        parsed = parse_numeric(text)
        return parsed if parsed is not None else text
    return text  # text stays text


def find_experiment_json(elab_id):
    """Find experiment JSON file."""
    paths = [
        Path(f"../experiment_{elab_id}.json"),
        Path(f"../data/experiment_{elab_id}.json"),
    ]
    for p in paths:
        if p.exists():
            return p
    raise FileNotFoundError(f"Experiment JSON not found for {elab_id}")


def load_workflow():
    """Load workflow.json and extract lab_id."""
    workflow_path = Path("../workflow.json")
    if workflow_path.exists():
        with open(workflow_path) as f:
            data = json.load(f)
            return data, data.get("lab_id") or data.get("labId")
    return None, None


def extract_metadata(extra_fields):
    """Extract and map metadata from eLabFTW extra fields.

    Applies FIELD_MAPPING and uses parse_field with eLabFTW field types
    to safely coerce numeric single values while correctly handling lists.
    """

    metadata = {}
    for elab_name, db_name in FIELD_MAPPING.items():
        if elab_name not in extra_fields:
            continue
        field = extra_fields[elab_name]
        value = field.get("value")
        field_type = field.get("type")  # e.g. 'number' or 'text'
        parsed_value = parse_field(value, field_type=field_type)
        metadata[db_name] = parsed_value
    return metadata


def list_folder_files(folder_path):
    """List files in a folder."""
    folder = Path(folder_path)
    if folder.exists():
        return [f.name for f in folder.iterdir() if f.is_file()]
    return []


def build_raw_data(elab_id):
    """Build raw_data JSONB structure."""
    data_folder = Path("../data")
    return {
        "folder_path": str(data_folder.resolve()),
        "files": list_folder_files(data_folder),
    }


def _load_analysis_results(elab_id):
    """Helper to load analysis_results_<id>.json if present.

    Returns parsed JSON dict or None if not found/invalid.
    """

    results_json_path = Path("../results") / f"analysis_results_{elab_id}.json"
    if not results_json_path.exists():
        return None
    try:
        with open(results_json_path, "r") as f:
            return json.load(f)
    except Exception:
        return None


def build_results(elab_id):
    """Build results JSONB structure from analysis outputs.

    Integrates with the AKTA analysis script convention:
    - analysis_results_<id>.json in ../results
    - akta_processed_<id>.csv in ../results
    - chromatogram_<id>.png/.pdf in ../results
    """

    results_folder = Path("../results")
    analysis_json = _load_analysis_results(elab_id)

    timestamp = datetime.now(timezone.utc).isoformat()

    # Default values
    analysis_status = "pending"
    summary = {
        "data_source": None,
        "files_processed": None,
        "n_peaks": None,
    }
    peaks = []
    data_files = {}
    plots = {}

    if analysis_json is not None:
        # Map status from analysis script to our enum
        status_raw = analysis_json.get("status")
        if status_raw == "success":
            analysis_status = "completed"
        elif status_raw in {"failed", "error"}:
            analysis_status = "failed"
        else:
            analysis_status = "pending"

        meta = analysis_json.get("metadata", {})
        if isinstance(meta, dict):
            summary["data_source"] = meta.get("data_source")

        summary["files_processed"] = analysis_json.get("files_processed")

        peaks_list = analysis_json.get("peaks") or []
        if isinstance(peaks_list, list):
            peaks = peaks_list
            summary["n_peaks"] = len(peaks_list)

        # Data outputs
        data_outputs = analysis_json.get("data_outputs", {})
        if isinstance(data_outputs, dict):
            if data_outputs.get("processed_csv"):
                data_files["processed_csv"] = data_outputs["processed_csv"]
            if data_outputs.get("results_json"):
                data_files["results_json"] = data_outputs["results_json"]

        # Plot paths in analysis JSON are absolute; keep them if present
        plots_json = analysis_json.get("plots", {})
        chrom = plots_json.get("chromatogram", {}) if isinstance(plots_json, dict) else {}
        if isinstance(chrom, dict):
            if chrom.get("png"):
                plots["chromatogram_png"] = chrom["png"]
            if chrom.get("pdf"):
                plots["chromatogram_pdf"] = chrom["pdf"]

    else:
        # No analysis JSON; still attempt to infer files by path convention
        processed_csv = results_folder / f"akta_processed_{elab_id}.csv"
        if processed_csv.exists():
            data_files["processed_csv"] = str(processed_csv.resolve())

        res_json_path = results_folder / f"analysis_results_{elab_id}.json"
        if res_json_path.exists():
            data_files["results_json"] = str(res_json_path.resolve())

        png_path = results_folder / f"chromatogram_{elab_id}.png"
        pdf_path = results_folder / f"chromatogram_{elab_id}.pdf"
        if png_path.exists():
            plots["chromatogram_png"] = str(png_path.resolve())
        if pdf_path.exists():
            plots["chromatogram_pdf"] = str(pdf_path.resolve())

        analysis_status = "pending"

    return {
        "analysis_status": analysis_status,
        "analysis_timestamp": timestamp,
        "summary": summary,
        "peaks": peaks,
        "data_files": data_files,
        "plots": plots,
        "raw_analysis": analysis_json,
    }


# ============================================================================
# MAIN FUNCTIONS
# ============================================================================


def upsert_process_schema(cursor):
    """Insert or update process schema."""

    cursor.execute(
        """
        INSERT INTO process_schemas (
            process_id, process_name, version,
            metadata_schema, results_schema, field_mapping, expected_files
        ) VALUES (%s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (process_id) DO UPDATE SET
            process_name = EXCLUDED.process_name,
            metadata_schema = EXCLUDED.metadata_schema,
            results_schema = EXCLUDED.results_schema,
            field_mapping = EXCLUDED.field_mapping,
            expected_files = EXCLUDED.expected_files,
            updated_at = NOW()
        """,
        (
            PROCESS_ID,
            PROCESS_NAME,
            PROCESS_VERSION,
            json.dumps(METADATA_SCHEMA),
            json.dumps(RESULTS_SCHEMA),
            json.dumps(FIELD_MAPPING),
            json.dumps(EXPECTED_FILES),
        ),
    )


def upsert_experiment(cursor, elab_id, data):
    """Insert or update experiment execution."""

    cursor.execute(
        """
        INSERT INTO experiment_executions (
            elab_id, elab_title, process_id, process_name, lab_id,
            status, "user", workflow_json, metadata, raw_data, results
        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (elab_id) DO UPDATE SET
            elab_title = EXCLUDED.elab_title,
            status = EXCLUDED.status,
            metadata = EXCLUDED.metadata,
            raw_data = EXCLUDED.raw_data,
            results = EXCLUDED.results,
            workflow_json = EXCLUDED.workflow_json,
            updated_at = NOW()
        RETURNING id
        """,
        (
            elab_id,
            data["title"],
            PROCESS_ID,
            PROCESS_NAME,
            data["lab_id"],
            data["status"],
            data["user"],
            json.dumps(data["workflow_json"]) if data["workflow_json"] is not None else None,
            json.dumps(data["metadata"]),
            json.dumps(data["raw_data"]),
            json.dumps(data["results"]),
        ),
    )
    row = cursor.fetchone()
    return row[0] if row else None


def main():
    parser = argparse.ArgumentParser(
        description=f"Commit {PROCESS_NAME} to database"
    )
    parser.add_argument("elab_id", type=int, help="eLabFTW experiment ID")
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Don't commit, just show what would be done",
    )
    parser.add_argument(
        "--init-schema-only",
        action="store_true",
        help="Only initialize process schema",
    )
    args = parser.parse_args()

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        # Always upsert schema
        upsert_process_schema(cursor)
        print(f"Process schema updated: {PROCESS_NAME} (ID: {PROCESS_ID})")

        if args.init_schema_only:
            conn.commit()
            print("Schema-only mode, skipping experiment data.")
            return 0

        # Load experiment data
        exp_json_path = find_experiment_json(args.elab_id)
        with open(exp_json_path) as f:
            exp_data = json.load(f)

        # Extract fields
        extra_fields = exp_data.get("metadata_decoded", {}).get("extra_fields", {})
        workflow_json, lab_id = load_workflow()

        # Build data structures
        data = {
            "title": exp_data.get("title", ""),
            "lab_id": lab_id,
            "status": "completed",
            "user": exp_data.get("userid_human", ""),
            "workflow_json": workflow_json,
            "metadata": extract_metadata(extra_fields),
            "raw_data": build_raw_data(args.elab_id),
            "results": build_results(args.elab_id),
        }

        if args.dry_run:
            print("DRY RUN - Would insert:")
            print(json.dumps(data, indent=2, default=str))
            if conn is not None:
                conn.rollback()
            return 0

        # Commit to database
        exp_db_id = upsert_experiment(cursor, args.elab_id, data)
        conn.commit()

        print(
            f"Experiment {args.elab_id} committed successfully (DB ID: {exp_db_id})"
        )
        return 0

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        if conn is not None:
            conn.rollback()
        return 1
    finally:
        if conn is not None:
            conn.close()


if __name__ == "__main__":
    sys.exit(main())
